    this.historyTurns = cachedHistory;
    this.historyLoaded = cachedHistory.length > 0;
    const previousView = previousId ? this.views.get(previousId) : null;
    this.activeId = id;
    this.updateEventlyDemoFeatureBanner();
    this.updateRecentFilesWatch();
